package io.knowledgebrain.learning;
import java.util.*;import java.io.IOException;import jakarta.servlet.http.HttpServletRequest;import org.springframework.web.bind.annotation.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.web.server.ResponseStatusException;import io.micrometer.core.instrument.MeterRegistry;
@RestController @ConditionalOnProperty(name="brain.learning.api.enabled",havingValue="true")
@RequestMapping("/api/groups/{groupId}/courses/{courseId}")
final class CourseProgressShareController {
 private final CourseProgressShareStore store;private final CourseContextClient context;private final RoadmapController body;private final MeterRegistry metrics;private final String origin;
 CourseProgressShareController(CourseProgressShareStore store,CourseContextClient context,RoadmapController body,MeterRegistry metrics,@Value("${brain.learning.browser-origin}")String origin){this.store=store;this.context=context;this.body=body;this.metrics=metrics;this.origin=origin;}
 private void query(HttpServletRequest r,Set<String> allowed){if(r.getQueryString()!=null&&r.getQueryString().length()>256)throw RoadmapGraph.bad();RoadmapController.parameters(r,allowed);}
 private String token(HttpServletRequest r,boolean write){if(!r.isSecure())throw RoadmapGraph.bad();if(write&&(Collections.list(r.getHeaders("Origin")).size()!=1||!origin.equals(r.getHeader("Origin"))||r.getHeader("Sec-Fetch-Site")!=null&&!r.getHeader("Sec-Fetch-Site").equals("same-origin")))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Same-origin request required");var tokens=new ArrayList<String>();for(var h:Collections.list(r.getHeaders("Cookie")))for(var part:h.split(";")){var pair=part.strip().split("=",2);if(pair.length==2&&pair[0].equals("__Host-brain_guest"))tokens.add(pair[1]);}if(tokens.size()!=1||!tokens.getFirst().matches("[A-Za-z0-9_-]{43}"))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Session required");return tokens.getFirst();}
 private CourseContextClient.Sharing access(String group,String course,HttpServletRequest r,boolean write){return context.sharing(RoadmapGraph.id(group),RoadmapGraph.id(course),token(r,write),RoadmapController.parent(r),List.of());}
 private ResponseEntity<?> response(Object v,long version){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).eTag("\"cs"+version+"\"").body(v);}
 @GetMapping("/my-progress/owner-share") ResponseEntity<?> get(@PathVariable String groupId,@PathVariable String courseId,HttpServletRequest r){query(r,Set.of());var a=access(groupId,courseId,r,false);var v=store.get(a);metrics.counter("brain.learning.course.summary.reads","type","own").increment();return response(v,v.share()==null?0:v.share().version());}
 @PutMapping("/my-progress/owner-share") ResponseEntity<?> change(@PathVariable String groupId,@PathVariable String courseId,HttpServletRequest r)throws IOException{query(r,Set.of());var a=access(groupId,courseId,r,true);long expected=LearningStudyController.version(r,"cs",true);var v=body.body(r,4096);if(!v.path("state").isString())throw RoadmapGraph.bad();String state=v.path("state").asString();long source=0;if(state.equals("WITHDRAWN")){if(v.size()!=1)throw RoadmapGraph.bad();}else if(state.equals("SHARED")){if(v.size()!=6)throw RoadmapGraph.bad();for(String n:List.of("progressVersion","policyVersion","courseVersion","enrollmentVersion","membershipVersion"))if(!v.path(n).isIntegralNumber()||!v.path(n).canConvertToLong()||v.path(n).asLong()<1)throw RoadmapGraph.bad();if(v.path("policyVersion").asLong()!=a.policyVersion()||v.path("courseVersion").asLong()!=a.learning().courseVersion()||v.path("enrollmentVersion").asLong()!=a.learning().enrollmentVersion()||v.path("membershipVersion").asLong()!=a.membershipVersion())throw new ResponseStatusException(HttpStatus.CONFLICT,"Sharing context changed; review again");source=v.path("progressVersion").asLong();}else throw RoadmapGraph.bad();var result=store.change(a,expected,state,source,RoadmapController.parent(r).substring(3,35));metrics.counter("brain.learning.course.summary.changes","state",state).increment();return response(result,result==null?0:result.version());}
 @GetMapping("/my-progress/owner-share/revisions") ResponseEntity<?> history(@PathVariable String groupId,@PathVariable String courseId,HttpServletRequest r){query(r,Set.of("before","limit"));var a=access(groupId,courseId,r,false);return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(store.history(a,RoadmapController.number(r.getParameter("before"),Long.MAX_VALUE,Long.MAX_VALUE),(int)RoadmapController.number(r.getParameter("limit"),5,10)));}
 @GetMapping("/shared-progress") ResponseEntity<?> list(@PathVariable String groupId,@PathVariable String courseId,HttpServletRequest r){query(r,Set.of("after","limit"));var a=access(groupId,courseId,r,false);if(!a.learning().role().equals("OWNER"))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Group OWNER required");UUID after=r.getParameter("after")==null?null:RoadmapGraph.id(r.getParameter("after"));int limit=(int)RoadmapController.number(r.getParameter("limit"),20,100);var scan=store.scan(a,after,limit);var fresh=a;if(!scan.items().isEmpty()){fresh=context.sharing(a.learning().groupId(),a.learning().courseId(),token(r,false),RoadmapController.parent(r),scan.items().stream().map(CourseProgressShareStore.Share::participantId).toList());if(!fresh.learning().principalId().equals(a.learning().principalId())||!fresh.learning().spaceId().equals(a.learning().spaceId())||fresh.policyVersion()!=a.policyVersion()||fresh.enabled()!=a.enabled())throw new ResponseStatusException(HttpStatus.CONFLICT,"Sharing policy changed; refresh");}metrics.counter("brain.learning.course.summary.reads","type","owner").increment();return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(CourseProgressShareStore.filter(scan,fresh));}
}
